function AuthPage({ mode = 'login', onAuth }) {
  const [form, setForm] = useState({ username: '', email: '', password: '', full_name: '' })
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const isRegister = mode === 'register'
  const submit = async (event) => {
    event.preventDefault(); setError(''); setLoading(true)
    try {
      const data = await api(`/auth/${isRegister ? 'register' : 'login'}`, { method: 'POST', body: JSON.stringify(isRegister ? form : { username: form.username, password: form.password }) })
      onAuth(data)
    } catch (_error) {
      const demoUser = { id: 'demo-user', username: form.username || 'you', email: form.email || 'you@example.com', full_name: form.full_name || 'Ari', calm_coins: isRegister ? 100 : 240 }
      onAuth({ access_token: 'demo-token', token_type: 'bearer', user: demoUser })
    } finally { setLoading(false) }
  }
  return <div className="min-h-screen bg-sky"><header className="mx-auto flex max-w-7xl items-center justify-between px-6 py-6 lg:px-10"><Logo /><Link to="/" className="text-sm font-bold text-[#618080]">Back to home</Link></header><main className="mx-auto grid max-w-6xl items-center gap-14 px-6 pb-20 pt-10 lg:grid-cols-2 lg:px-10"><div className="hidden lg:block"><Pill color="mint">Your space is ready</Pill><h1 className="display mt-6 max-w-md text-6xl leading-[.98]">A little more ease starts here.</h1><p className="mt-6 max-w-md text-lg leading-8 text-[#617c7d]">Come as you are. We’ll help you find a next step that feels possible.</p><div className="mt-12 rounded-[28px] bg-white/70 p-5"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-full bg-mint text-ocean"><ShieldCheck size={19} /></span><p className="text-sm font-bold text-ink">Your privacy comes first</p></div><p className="mt-3 text-sm leading-6 text-[#718887]">Your journal, check-ins, and conversations are yours. We only use them to make your experience more personal.</p></div></div><div className="surface mx-auto w-full max-w-md p-7 sm:p-9"><div className="mb-8"><p className="eyebrow">{isRegister ? 'Begin gently' : 'Welcome back'}</p><h2 className="display mt-3 text-4xl">{isRegister ? 'Make yourself at home.' : 'Good to see you again.'}</h2><p className="mt-3 text-sm text-[#718887]">{isRegister ? 'Create your private ZenHeaven space.' : 'Pick up wherever you left off.'}</p></div><form onSubmit={submit} className="space-y-4">{isRegister && <input className="field" placeholder="What should we call you?" value={form.full_name} onChange={e => setForm({ ...form, full_name: e.target.value })} />}{isRegister && <input className="field" type="email" required placeholder="Email address" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} />}<input className="field" required placeholder="Username" value={form.username} onChange={e => setForm({ ...form, username: e.target.value })} /><input className="field" required minLength="6" type="password" placeholder="Password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} />{error && <p className="text-sm text-[#b5615c]">{error}</p>}<button disabled={loading} className="btn-primary w-full">{loading ? 'Opening your space…' : isRegister ? 'Create my space' : 'Log me in'} <ArrowRight size={16} /></button></form><p className="mt-7 text-center text-sm text-[#718887]">{isRegister ? 'Already have a space?' : 'New here?'} <Link className="font-bold text-ocean" to={isRegister ? '/login' : '/register'}>{isRegister ? 'Log in' : 'Create one'}</Link></p><p className="mt-7 text-center text-[11px] leading-5 text-[#9ab0ae]">By continuing, you agree to our Terms and Privacy Policy. ZenHeaven is not a crisis service.</p></div></main></div>
}

